import { Directive, ElementRef, Input, OnChanges, Renderer2 } from '@angular/core';

@Directive({
  selector: '[appHighlight]'
})
export class HighlightDirective implements OnChanges {
  @Input('appHighlight') word: string = '';
  private highlightedElements: HTMLElement[] = [];

  constructor(private el: ElementRef, private renderer: Renderer2) {}

  ngOnChanges() {
    this.removeHighlights();
    if (this.word) {
      this.highlightWords(this.word);
    }
  }

  private highlightWords(word: string) {
    const regex = new RegExp(`(${word})`, 'gi');
    const content = this.el.nativeElement.innerHTML;
    const highlightedContent = content.replace(regex, '<span class="highlight">$1</span>');
    this.el.nativeElement.innerHTML = highlightedContent;

    this.highlightedElements = Array.from(this.el.nativeElement.querySelectorAll('.highlight'));
  }

  private removeHighlights() {
    this.highlightedElements.forEach(element => {
      const parent = element.parentNode;
      if (parent) {
        parent.replaceChild(document.createTextNode(element.textContent || ''), element);
      }
    });
  }
}


