class SinglyLinkedList:
    def __init__(self):
        self.head = None
        self.values_set = set()

    def insert_at_beginning(self, data):
        if data not in self.values_set:
            new_node = Node(data)
            new_node.next = self.head
            self.head = new_node
            self.values_set.add(data)

    def insert_at_end(self, data):
        if data not in self.values_set:
            new_node = Node(data)
            if not self.head:
                self.head = new_node
            else:
                current = self.head
                while current.next:
                    current = current.next
                current.next = new_node
            self.values_set.add(data)

    def insert_at_position(self, data, position):
        if data not in self.values_set:
            new_node = Node(data)
            if position == 0:
                new_node.next = self.head
                self.head = new_node
            else:
                current = self.head
                for _ in range(position - 1):
                    if current is None:
                        return
                    current = current.next
                if current is not None:
                    new_node.next = current.next
                    current.next = new_node
            self.values_set.add(data)

This solution implements a singly linked list with methods to insert nodes at the beginning, end, and a specific position, ensuring no duplicate values are added.
